/* Reference UI: no remote calls, host execution or real human review submission. */
const icons={asset:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',make:'M4 20l4-1L20 7l-3-3L5 16z M14 7l3 3',result:'M5 3h10l4 4v14H5z M9 12h6 M9 16h6',link:'M9 15l6-6 M8 6l2-2a5 5 0 017 7l-2 2 M16 18l-2 2a5 5 0 01-7-7l2-2',upload:'M12 16V3 M7 8l5-5 5 5 M3 16v5h18v-5',settings:'M12 8a4 4 0 100 8 4 4 0 000-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M19 5l-2 2 M7 17l-2 2',clock:'M12 3a9 9 0 100 18 9 9 0 000-18 M12 6v6l4 2',check:'M4 12l5 5L20 6',info:'M12 3a9 9 0 100 18 9 9 0 000-18 M12 11v6 M12 7v1',play:'M8 4l12 8-12 8z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[n]||icons.info}"/></svg>`;
const art=(name,cls='media')=>`<img class="${cls}" src="../assets/art/${name}.svg" alt="${{'design-orbit':'冷蓝银白环形方法主视觉','brand-poster':'品牌海报版式','editorial':'出版双页布局','packaging':'包装盒等轴示意','spatial':'空间墙面视觉示意','interface':'应用界面图形示例','motion':'轨道动效静帧','teaching':'成功信号与实际验收三层对照','version-before':'海报修改前版本一','version-after':'海报修改后版本二'}[name]||name}">`;
const badge=(text,color='')=>`<span class="badge ${color}">${text}</span>`;
const btn=(text,href,cls='')=>href?`<button class="${cls}" type="button" data-route="${href}">${text}</button>`:`<button class="${cls}" type="button" data-action="draft">${text}</button>`;
const head=(eye,title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${desc}</p></div><div class="row">${actions}</div></div>`;
const panel=(title,content,extra='')=>`<section class="panel" data-component="${title}"><div class="panel-header"><h2>${title}</h2>${extra}</div>${content}</section>`;
const facts=rows=>`<dl class="facts">${rows.map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('')}</dl>`;
const notice=(text,color='')=>`<div class="notice ${color}">${text}</div>`;
const steps=active=>`<div class="stepper">${['输入与目标','分析与方案','制作与核验','成果与反馈'].map((x,i)=>`<span class="${i===active?'current':''}">${String(i+1).padStart(2,'0')}　${x}</span>`).join('')}</div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table class="table"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const numbered=rows=>`<ul class="list">${rows.map(([t,d],i)=>`<li><span class="number">${i+1}</span><div><strong>${t}</strong><p>${d}</p></div></li>`).join('')}</ul>`;
const caps=[
 {id:'type',name:'品牌海报与字体层级',domain:'品牌 / 平面',desc:'建立阅读顺序，保留准确文案，输出可修改的版式方案。',art:'brand-poster',tag:'分析 · 生成包',level:'原生交付待验证'},
 {id:'editorial',name:'出版版式与信息节奏',domain:'字体 / 出版',desc:'从网格、字号与留白出发，组织长文与双页关系。',art:'editorial',tag:'分析 · 生成包',level:'软件执行待验证'},
 {id:'packaging',name:'包装结构与视觉延展',domain:'包装 / 品牌',desc:'区分结构尺寸与装饰图形，锁定刀模及文字区域。',art:'packaging',tag:'分析',level:'结构核验未完成'},
 {id:'spatial',name:'空间视觉与透视约束',domain:'空间 / 展示',desc:'锁视角、比例与墙体关系，规划材质、字面及安装层级。',art:'spatial',tag:'分析 · 生成包',level:'宿主能力待确认'},
 {id:'interface',name:'界面系统与组件一致性',domain:'交互 / UI',desc:'把信息架构、视觉变量与组件状态落实到页面。',art:'interface',tag:'分析 · 生成包',level:'交付按环境核验'},
 {id:'teaching',name:'知识图解与教学表达',domain:'教学 / 动效',desc:'根据学习目标选择对照图、演示或判断练习。',art:'teaching',tag:'表达方案',level:'AAOS 实联未测试'}];
function catalog(){return head('CAPABILITY ASSETS','找到方法，再开始制作。','按问题选择能力，查看示例、适用条件与实际交付范围。',btn('开始新制作','input','primary'))+`<section class="hero" data-component="能力目录主视觉"><div class="hero-text"><div class="eyebrow">KNOWLEDGE → METHOD → MAKING</div><h2>让专业知识成为可调用的设计能力。</h2><p>从版式、风格到原生制作，用清晰的输入、约束与结果检查连接每一步。</p><div class="row">${badge('全品类专业范围','blue')}${badge('能力按实际证据声明')}</div></div>${art('design-orbit','')}</section><div class="catalog-layout"><aside class="filters" aria-label="能力筛选"><div><div class="filter-title">设计领域</div>${['全部领域',...caps.map(c=>c.domain)].map((x,i)=>`<button class="filter-button ${i===0?'selected':''}" data-domain="${x}">${x}</button>`).join('')}</div><div><div class="filter-title">能力层级</div>${['分析与建议','目标生成包','软件执行','原生交付'].map(x=>`<button class="filter-button" data-level="${x}">${x}</button>`).join('')}<div class="filter-title">分类与风格</div><small>构图 · 字体 · 色彩<br>材质 · 空间 · 运动<br>方法 · 输出结构</small></div></aside><section><div class="searchbar"><label class="hidden" for="search">搜索能力</label><input id="search" type="search" placeholder="搜索问题、方法、风格或软件"><button data-action="filter">更多筛选</button>${badge('6 项示例记录')}</div><div class="cards" id="capCards">${caps.map(c=>`<article class="cap-card" data-domain-value="${c.domain}" data-name="${c.name} ${c.desc}" data-component="能力卡-${c.id}">${art(c.art,'')}<div class="card-body"><small>${c.domain}</small><h3>${c.name}</h3><p>${c.desc}</p><div class="row wrap">${badge(c.tag,'blue')}</div><div class="card-bottom"><span>${c.level}</span>${btn('查看能力','capability')}</div></div></article>`).join('')}</div><div id="no-results" class="notice hidden">没有匹配能力。调整筛选条件，或从文字需求开始。</div></section></div>`;}
function capability(){return head('CAPABILITY / TYPE & LAYOUT','品牌海报与字体层级','先建立信息层级，再选择适配软件；准确文字优先使用原生排版。',btn('使用此能力','input','primary'))+`<div class="grid2"><div class="stack">${panel('示例与适用场景',art('brand-poster','media large')+`<div class="row wrap" style="margin-top:16px">${badge('原创版式')}${badge('精确文案')}${badge('局部改稿')}${badge('品牌延展')}</div>`)}${panel('它能帮助你完成什么',numbered([['组织阅读顺序','根据主标题、辅助信息、品牌标识建立层级。'],['生成可执行的目标包','明确尺寸、网格、参考职责、精确文字及允许变化范围。'],['检查与继续改稿','对照目标核对实际产物；可编辑性需宿主读回证明。']]))}</div><div class="stack">${panel('输入与交付范围',facts([['输入','文字需求 / 参考图 / 现有文件'],['输出','分析、目标生成包、原生操作计划'],['能力状态',badge('示例数据','amber')+' 原生执行待验证'],['适用条件','海报、品牌宣发与信息型视觉'],['不适用情况','未知刀模、未授权字体或未经核验的教学内容'],['知识版本','预览快照 k-layout@3（虚构 ID）'],['费用 / 权限','由目标宿主与执行器返回实际条件']]))}${panel('实现路线',numbered([['Illustrator / Photoshop','按已安装版本核验文本、路径与图层支持。'],['外部 Agent / 生成工具','提供能力包；无法锁定的约束明确说明。'],['人工交接','保留生成包与验收要求，不宣称已自动执行。']]))}${notice('此页展示产品规格。图示样例不能证明本机宿主已经接通。')}<details><summary>展开来源、许可与验证记录</summary><p>读取真实 knowledge_refs、资格与证据；没有记录显示未知，不推断通过。</p></details></div></div>`;}
function input(){return head('ANALYZE & MAKE','描述目标，放入参考。','短任务可以直接开始；只有需要时才补充项目、方向与设计系统。',btn('查看演示分析','analysis','primary'))+steps(0)+`<div class="grid2"><div class="stack">${panel('输入内容',`<div class="upload" data-component="多模态上传区">${icon('upload')}<h3>选择文件，或在下方描述需求</h3><small>截图、多图、文件、音视频；支持类型与大小由实际环境返回</small><input id="files" type="file" multiple aria-label="选择输入文件"></div><div id="filelist" class="micro">展示 3 份演示参考；选择文件仅记录名称，不上传。</div><div class="thumbstrip" style="margin-top:13px">${art('brand-poster','')}${art('editorial','')}${art('packaging','')}</div><label style="margin-top:18px"><span class="field-label">需求描述</span><textarea id="brief">制作一张品牌活动海报。保持冷蓝与银白的视觉方向，主标题使用“FORM STUDIES”，文字必须准确。环形主体可以调整大小；不要改变画幅比例。</textarea></label>`)}${panel('参考职责与编辑范围',`<div class="fields"><label><span>参考 01 的用途</span><select><option>构图与品牌语言</option><option>仅风格</option><option>结构锁定</option></select></label><label><span>参考 02 的用途</span><select><option>字体层级与留白</option><option>精确内容</option></select></label><label class="full"><span>必须保持</span><input value="画幅比例 / 主标题内容 / 冷蓝银白配色"></label><label class="full"><span>允许改变</span><input value="主体尺度 / 字体大小 / 细节纹理"></label></div>`)} </div><div class="stack">${panel('选择本次交付',`<div class="fields"><label class="full"><span>交付目标</span><select id="deliverable"><option>目标生成包</option><option>分析与建议</option><option>原生可编辑工程（需验证）</option><option>最终媒体文件</option></select></label><label><span>画幅</span><input value="1920 × 1080 px"></label><label><span>目标软件</span><select><option>Illustrator / 按环境确认</option><option>Photoshop / 按环境确认</option><option>提示词 / 人工交接</option></select></label><label class="full"><span>准确文案</span><textarea style="min-height:76px">FORM STUDIES · BEYOND / 01 · TYPE · SPACE · SYSTEM</textarea></label></div>`)}${panel('使用的能力与知识',`<div class="sample-chip">${icon('asset')}品牌海报与字体层级</div><p class="muted">知识引用固定到版本；来源与条件可在分析后查看。</p><div class="line"></div><label class="checkrow"><input type="checkbox"><span>需要制作知识讲解或教学内容<br><small>课程状态由 AAOS 管理。</small></span></label>`)}${notice('输入文件与客户材料留在本次任务域；反馈回流范围单独选择。')} ${btn('导入教学需求','teaching')}</div></div>`;}
function analysis(){return head('ANALYSIS / DESIGN INTENT','把需求整理成可检查的方案。','结构、风格和内容约束分别记录；不确定的推断允许你直接纠正。',btn('形成目标包','plan','primary'))+steps(1)+`<div class="grid2"><div class="stack">${panel('设计意图与参考分工',`<div class="grid2 equal">${art('brand-poster','media')}<div>${badge('演示分析','amber')}<h3 style="margin-top:16px">信息优先，环形主体为视觉锚点。</h3><p class="muted">标题与主体保持稳定关系；银白材质只用于焦点。</p><div class="line"></div>${facts([['参考 01','构图与色彩语言'],['参考 02','字体节奏'],['参考 03','材质气质'],['识别局限','未知原始图层与遮挡内容']])}</div></div>`)}${panel('方向与约束',table(['要素','本次方案','约束类型'],[['主标题','FORM STUDIES，原生文本排版',badge('必须保持','blue')],['环形主体','居中，缩放范围 85%–100%','允许改变'],['材质','冷蓝金属与银白高光','风格偏好'],['版式','标题 → 主体 → 次级信息','专业方法'],['准确性','不能推断版权或未知结构',badge('待确认','amber')]]))}${panel('纠正分析',`<div class="row"><input id="correction" placeholder="例如：参考 02 只参考留白，不参考字体"><button data-action="correct">保存本次纠正</button></div>`)} </div><div class="stack">${panel('依据与边界',numbered([['设计知识引用','绑定预览快照 k-layout@3；运行以 AAOS revision 为准。'],['软件能力','精确文案采用原生文本；未验证时输出生成包。'],['产物检查','视觉、原生读回与真人结论分别记录。']]))}${panel('路线建议',facts([['推荐','目标包 → 宿主核验 → 原生计划'],['降级','仅提示词 / 人工交接'],['不能保证','单次生成中文字、图层及位置完全锁定'],['本次预算','尚未调用付费工具'],['下一步','确认目标包或修改约束']]))}${notice('断网快照模式可继续分析；已撤销或需要在线复核的依据不能静默使用。')}</div></div>`;}
const planText=['任务：制作 FORM STUDIES 品牌活动海报。','输出：1920 × 1080 px，预览文件 + 目标生成包。','文案：FORM STUDIES / BEYOND / 01 / TYPE · SPACE · SYSTEM。','保持：画幅、准确文字、冷蓝银白色彩语言。','可变：环形主体尺度、辅助字号、局部材质。','制作：网格组织 → 原生排字 → 放置图形 → 对照核验。','检查：准确文字、图形位置、对比度、输出规格。','局限：宿主执行尚未实测，参考图不证明原生结构。'].join('\n');
function plan(){return head('PLAN / TARGET PACKAGE','目标包已可审阅，执行条件待确认。','用户查看制作步骤与约束；结构化操作计划由系统衔接。',`<button data-action="download-plan">下载演示目标包</button>${btn('查看执行演示','running','primary')}`)+steps(1)+`<div class="grid2"><div class="stack">${panel('目标生成包',`<div class="tabs"><span class="selected">制作说明</span></div><div class="codebox" id="plan-text">${planText}</div><div class="row" style="margin-top:15px"><button data-action="copy-plan">复制制作说明</button>${badge('引用版本固定','blue')}</div>`)}${panel('制作步骤',numbered([['确认宿主、输入与输出','读取真实版本与文档身份，检查冲突占用。'],['创建或修改原生对象','使用文本、路径与图层操作，保留无关对象。'],['核验后保存并读回','截图检查视觉，结构读回检查可编辑性。'],['交付或交接','不满足条件时返回生成包及继续方式。']]))}</div><div class="stack">${panel('执行条件',facts([['任务','demo-poster-01'],['宿主','未连接（预览环境）'],['动作范围','创建文档 / 排版 / 保存'],['输入版本','brief@1 / references@1'],['知识版本','k-layout@3（演示）'],['文档占用','真实执行前由后端检查'],['费用','执行前获取实际预算'],['恢复点','复用现有 NativeWorkers 合同']]))}${notice('原型只演示界面，不会操作宿主或调用外部 Agent。','amber')}${panel('可用的降级方式',`<p class="muted">保留目标包，交给外部 Agent 或人工制作；降级结果不能标成原生自动执行。</p><div class="row" style="margin-top:15px">${btn('返回修改','input')}${btn('查看交接','delivery')}</div>`)}</div></div>`;}
function running(){return head('EXECUTION / NATIVE PLAN','制作进行中，核验随后发生。','执行动作成功与产物合格分别记录；当前是状态演示。',`<button data-action="pause" id="pause">暂停演示</button>${btn('查看恢复状态','recovery')}`)+steps(2)+`<div class="grid2"><div class="stack">${panel('最近可见结果',art('version-after','media large')+`<div class="row spread" style="margin-top:15px">${badge('草稿 v2 · 演示','blue')}<small>原生结构未核验</small></div>`)}${panel('执行步骤',`<ol class="timeline"><li><span class="number">✓</span><div><strong>输入与约束已读取</strong><p>示例 brief@1 / references@1 固定到当前运行。</p></div></li><li><span class="number">✓</span><div><strong>文本与图形已写入（演示）</strong><p>仅展示预期状态，未发生真实宿主写入。</p></div></li><li><span class="number">3</span><div><strong id="run-state">等待原生结构读回</strong><p>视觉截图不能证明文字、路径与图层可编辑。</p></div></li><li><span class="number">4</span><div><strong>保存、重开与交付预检</strong><p>待真实执行；按用户要求的交付格式核验。</p></div></li></ol>`)} </div><div class="stack">${panel('运行控制',`<div class="row spread"><strong id="run-label">演示运行中</strong>${badge('不连接宿主','amber')}</div><div class="progress"><span id="run-progress"></span></div>${facts([['当前动作','读取文本与图层结构'],['软件','Illustrator · 版本待核验'],['文档','demo-poster-01 / v2'],['占用范围','桌面、宿主与文档同一租约'],['耗费','预览不产生工具费用'],['预算截止','由真实后端返回']])}<div class="line"></div><button class="danger" data-action="cancel">取消演示</button>`)}${panel('观察与验证',numbered([['视觉核对','位置、比例、字体层级与目标对照。'],['原生结构读回','文字、路径、图层实际可编辑性。'],['真人评审','只对确定产物版本生效，AI 不代签。']]))}${notice('超时先核对文档与动作结果，再决定重试；不重复创建或导出。')}<details><summary>查看技术日志与版本引用</summary><p>生产中读取真实 run、lease、action receipt 与 checkpoint，未知状态不显示成功。</p></details></div></div>`;}
function recovery(){return head('RECOVERY / RECONCILIATION','先核对结果，再继续执行。','断开连接后保留输入、约束与最近结果；恢复方式取决于实际宿主读回。',btn('返回制作记录','running'))+notice('演示异常：宿主响应超时。尚未确认动作是否完成，自动重试暂停。','amber')+`<div class="grid2" style="margin-top:22px"><div class="stack">${panel('最后一个可见版本',art('version-after','media large')+`<p class="muted">v2 是演示预览；不能凭这张图判断文档已经保存。</p>`)}${panel('恢复需要核对的三件事',numbered([['文档身份是否一致','核对当前打开的文档、目标路径与上次写入范围。'],['动作实际是否完成','读取目标对象与输出文件，避免重复创建或导出。'],['恢复点是否有效','按读回结果继续、回滚或交给用户接管。']]))}</div><div class="stack">${panel('恢复选择',`<label class="checkrow"><input type="radio" name="recover" checked><span>核对宿主后继续<br><small>只执行尚未完成的动作。</small></span></label><div class="line"></div><label class="checkrow"><input type="radio" name="recover"><span>从上一恢复点重建计划<br><small>保留最新可确认结果及原始引用。</small></span></label><div class="line"></div><label class="checkrow"><input type="radio" name="recover"><span>转为人工交接<br><small>返回生成包、现状与未完成检查。</small></span></label><div class="row" style="margin-top:22px"><button class="primary" data-action="recover">演示核对并继续</button>${btn('查看交接材料','plan')}</div>`)}${panel('已保留的材料',facts([['输入','brief@1 / references@1'],['计划','native-plan@1（演示）'],['最近预览','draft@2（演示）'],['检查结果','原生读回未知'],['恢复状态','待真实宿主核对']]))}${notice('没有连接宿主时保留状态，不伪造恢复成功。')}</div></div>`;}
function results(){return head('RESULTS & FEEDBACK','找回成果，继续下一次修改。','分析结果、目标包、执行草稿与正式交付分别标识。',btn('开始新制作','input','primary'))+`<div class="tabs"><a class="selected" href="#results">全部成果</a><a href="#result">草稿与版本</a><a href="#delivery">交付包</a><a href="#feedback">反馈</a></div><div class="searchbar"><input aria-label="搜索成果" placeholder="搜索任务、产物或版本"><button data-action="filter">按交付类型筛选</button>${badge('示例集合')}</div><div class="outputcards">${[['version-after','FORM STUDIES 品牌海报','草稿 v2','原生结构待验证','result'],['teaching','成功信号与验收区别','教学表达样例','来源与学习效果未验证','teaching'],['packaging','ORBIT 包装视觉方向','分析方案','结构与刀模待核验','analysis'],['interface','界面信息层级整理','目标生成包','不代表已写入 Figma','plan'],['spatial','空间视觉约束说明','分析结果','保留视角与比例要求','analysis'],['motion','轨道动效表达方案','表达方案','静帧不代表时间轴工程','plan']].map(([a,n,v,s,r])=>`<article class="cap-card" data-component="成果卡-${r}-${a}">${art(a,'')}<div class="card-body"><small>${v}</small><h3>${n}</h3><p>${s}</p><div class="card-bottom"><span>本地演示数据</span>${btn('查看与继续',r)}</div></div></article>`).join('')}</div><div class="footnote"><span>示例成果用于界面预览，不是你的真实项目产物。</span><span>正式交付须绑定确切版本与实际检查结果。</span></div>`;}
function result(){return head('RESULT / VERSION 02','FORM STUDIES · 草稿 v2','版本、视觉检查、原生读回与真人意见互相独立。',`${btn('版本对比与评审','jury')}${btn('交付预检','delivery','primary')}`)+`<div class="grid2"><div class="stack">${panel('产物预览',art('version-after','media large')+`<div class="row spread" style="margin-top:14px">${badge('演示草稿','blue')}<div class="row">${badge('v1')}${badge('v2 · 当前','blue')}</div></div>`)}${panel('继续局部修改',`<label><span class="field-label">本次修改要求</span><textarea id="patch">主体再缩小 10%，保持标题位置与文案；不改变画幅与配色。</textarea></label><div class="row spread" style="margin-top:16px"><small>修改后生成新版本，旧评审结论不自动沿用。</small><button class="primary" data-action="patch">生成演示改稿计划</button></div>`)} </div><div class="stack">${panel('产物身份',facts([['产物','demo-poster-01 / draft@2'],['实际文件','version-after.svg（UI 样例）'],['声称格式','SVG 设计示例'],['原生工程','未连接宿主，未生成 AI / PSD'],['目标','视觉草稿与生成包'],['知识引用','k-layout@3（演示）']]))}${panel('检查结论',`<ul class="list"><li><span class="check">✓</span><div><strong>示例文件可显示</strong><p>仅指本包 SVG，不是宿主验收。</p></div></li><li>${icon('clock')}<div><strong>原生可编辑性待测试</strong><p>PNG 不代替 PSD；SVG 不证明 AI 工程。</p></div></li><li>${icon('clock')}<div><strong>真人评审待提交</strong><p>意见绑定 exact artifact revision。</p></div></li></ul>`)}${notice('对草稿可以直接提修改；只在正式交付需要时进行对应资格核验。')}${btn('提交制作反馈','feedback')}</div></div>`;}
function jury(){return head('HUMAN REVIEW / VERSION DIFF','对确切版本做真实决定。','预览可以准备差分和意见；只有真人决定才能形成生产评审回执。',btn('返回产物','result'))+`<div class="grid2"><div class="stack">${panel('版本对照',`<div class="version"><figure>${art('version-before','')}<figcaption><span>v1 · 修改前</span><span>主体 100%</span></figcaption></figure><figure>${art('version-after','')}<figcaption><span>v2 · 当前</span><span>主体 86%</span></figcaption></figure></div>`)}${panel('本次改变与保持',table(['对象','变化','核对'],[['环形主体','尺寸减小 14%','演示图形可见'],['主标题','字号减小，位置保持','精确文字可读'],['画幅 / 色彩','保持不变',badge('视觉对照','blue')],['原生对象 ID','真实宿主未运行',badge('未知','amber')]]))}${notice('这是样例差分。实际评审应引用真实产物 hash、版本与对象，不根据文件名判断。')}</div><div class="stack">${panel('评审意见草稿',`<div class="fields"><label class="full"><span>评审对象</span><input readonly value="demo-poster-01 / draft@2"></label><label class="full"><span>我的决定</span><select id="jury-decision"><option>要求修改</option><option>接受</option><option>拒绝</option></select></label><label class="full"><span>意见</span><textarea id="jury-note">主体缩小后信息层级更清楚。请继续核对标题边距与输出规格，再提交正式交付。</textarea></label></div><div class="line"></div><button class="primary" data-action="jury">保存本地评审草稿</button><p class="micro" id="jury-status">没有真实评审回执；预览不代签姓名与时间。</p>`)}${panel('决定适用范围',facts([['绑定版本','只对 draft@2 生效'],['修改之后','draft@3 必须重新判断'],['自动化检查','不能代替审美认可'],['生产回执','身份、权限与服务端时间由真实系统保存']]))}${notice('“接受视觉”与“正式交付合格”不是同一个状态。','amber')}</div></div>`;}
function delivery(){return head('DELIVERY / PREFLIGHT','把测试导出与正式交付分开。','按本次交付目标核对必要条件；缺少证据时保留草稿与交接材料。',`<button data-action="download-art">下载 SVG 演示文件</button><button disabled title="真实宿主与评审未完成">生成正式交付包</button>`)+`<div class="grid2"><div class="stack">${panel('交付资格',table(['检查项目','本次情况','状态'],[['准确文字与画幅','演示 SVG 可显示；实际产物待核对',badge('待检查','amber')],['权利与素材用途','示例图形本包创建；生产输入另查',badge('按产物核对')],['真人审美结论','仅可保存本地意见草稿',badge('未提交','amber')],['原生结构与依赖','未生成 AI / PSD；不声称已验证',badge('不适用 / 待核验')],['生产预检 / 隔离重开','实际宿主未运行',badge('未测试','amber')],['版本与文件清单','演示 SVG / 目标说明','示例可导出']]))}${panel('交接内容',table(['文件 / 材料','用途','性质'],[['version-after.svg','可显示的设计示例','演示资产'],['target-package.json','目标、文案与制作约束','合同样例'],['未完成检查清单','宿主、权利、评审与重开','待执行项']]))}</div><div class="stack">${panel('本次交付目标',facts([['选择','草稿 / 测试导出'],['产物版本','demo-poster-01 / draft@2'],['原生要求','需用户选择及宿主证据'],['可提供','SVG 样例与目标包'],['正式资格','尚未满足']]))}${notice('仅需要 PNG 时按 PNG 要求检查，不额外强加 PSD；声称原生工程时才验证对应结构。')}${panel('下一步',numbered([['接通实际宿主','保存、关闭、重开并读取结构。'],['完成必要的真人评审','对确切版本提交意见与回执。'],['形成正式交付','绑定权利、预检、依赖、BOM 与文件版本。']]))}</div></div>`;}
function feedback(){return head('FEEDBACK / KNOWLEDGE CANDIDATE','让反馈回到能解决它的地方。','本次纠正、个人偏好与通用知识候选分别保存；候选受理不等于核验通过。',btn('返回成果','results'))+`<div class="grid2"><div class="stack">${panel('记录问题与观察',`<div class="fields"><label><span>反馈关联</span><input readonly value="demo-poster-01 / draft@2"></label><label><span>知识版本</span><input readonly value="k-layout@3（演示）"></label><label class="full"><span>问题类别</span><select id="feedback-category"><option value="design">表达 / 教学问题 → DESIGN-LAB</option><option value="knowledge">知识 / 技术问题 → AAOS 核验</option><option value="runtime">运行 / 集成问题 → 实际执行模块</option></select></label><label class="full"><span>实际发生了什么</span><textarea id="feedback-note">教学对照图的第二个步骤解释不够清楚。建议补充“文件存在还需要检查内容与规格”的反例。</textarea></label><label class="full"><span>场景 / 题目 / 任务</span><input value="成功信号辨析 / 题目 Q2（演示）"></label></div>`)}${panel('用途与回流范围',`<div class="fields"><label class="full"><span>保存为</span><select id="feedback-scope"><option>仅本次纠正</option><option>个人偏好</option><option>通用知识候选（待核验）</option></select></label></div><div class="line"></div><label class="checkrow"><input id="allow-feedback" type="checkbox"><span>允许将必要摘要与获准证据回流 AAOS<br><small>不包含客户原件、私人会话或凭证。</small></span></label><div class="row" style="margin-top:20px"><button class="primary" data-action="save-feedback">保存本地反馈草稿</button><small>当前不会发送到其他项目。</small></div>`)} </div><div class="stack">${panel('接收与处理状态',facts([['负责人','DESIGN-LAB · 表达与制作'],['候选','尚未提交'],['AAOS 回执','不存在'],['核验','未进行'],['修订关系','按处理结果绑定新版本']])+`<div class="line"></div><div class="notice" id="feedback-status">保存草稿后可继续编辑；生产接入后显示真实幂等回执。</div>`)}${panel('避免错误归因',numbered([['没看懂 ≠ 知识错误','先核对表达、前置知识与题目设计。'],['播放完成 ≠ 已经掌握','AAOS 根据实际练习与应用记录学习。'],['同源成果 ≠ 多份证据','文章、图解与视频标记共同 source lineage。']]))}${notice('允许未经验证的经验先保存；用于教学或自动执行时另行判断资格。')}</div></div>`;}
function teaching(){return head('TEACHING REQUEST / SAME MAKING FLOW','把知识变成可理解的表达。','教学需求是一种制作任务；课程组织、练习与长期学习状态归 AAOS。',btn('进入制作方案','analysis','primary'))+`<div class="grid2"><div class="stack">${panel('教学需求',`<div class="fields"><label class="full"><span>主题</span><input value="任务显示成功，为什么还不一定算完成？"></label><label><span>目标人群</span><input value="刚开始使用 AI Agent 的开发者"></label><label><span>前置知识</span><input value="了解任务输入、输出与文件"></label><label class="full"><span>学习目标</span><textarea style="min-height:76px">能够区分命令成功、文件存在、业务要求满足，并选择对应验收方式。</textarea></label><label class="full"><span>易误解点</span><input value="把返回码、生成文件与实际完成当成同一个状态"></label></div>`)}${panel('推荐的表达组合',`<div class="grid2 equal">${art('teaching','media')}<div><h3>对照图 + 分步演示 + 判断练习</h3><p class="muted">先解释三个信号，再给出错误案例。学习者判断应检查什么，而不是只看动画。</p><div class="row wrap" style="margin-top:14px">${badge('图解','blue')}${badge('可暂停演示')}${badge('练习规则')}</div></div></div>`)}${panel('生产与学习各自的职责',table(['参与方','提供或负责','本样例状态'],[['WORK-LAB','真实案例、环境与技术复现','材料未接收'],['AAOS','知识版本、目标、课程与学习反馈','实联未测试'],['DESIGN-LAB','图解、演示、源工程与修订','表达样例已绘制']]))}</div><div class="stack">${panel('知识与交付引用',facts([['来源','AAOS 教学需求（演示）'],['知识','k-success@1（虚构 ID）'],['实践案例','WORK-LAB 待提供授权材料'],['输出','图解 / 演示 / 判断练习规则'],['源工程','保留在 DESIGN-LAB 制作域'],['课程登记','由 AAOS 接收与登记']]))}${panel('制作时一并考虑',numbered([['文本与字幕','按内容提供准确讲解文本与同步字幕。'],['必要视觉说明','补充理解图解与动画所必需的视觉信息。'],['练习与反馈规则','题目关联知识与内容版本，避免只统计播放。'],['依赖与限制','声明实际承载环境；未测试不称兼容 H5P。']]))}${notice('此图是教学表达样例，尚未用真实案例核验，也未证明学习效果。','amber')}</div></div>`;}
function connections(){return head('CONNECTIONS / AUXILIARY','按需要连接，保持独立可用。','查看实际状态、版本与降级方式；连接设置不占据产品首页。',btn('查看界面状态','states'))+`<div class="stack"><div class="connection" data-component="AAOS连接"><div class="row"><div class="connection-symbol">A</div><div><h3>AAOS / ArcheAxis</h3><p>知识版本、候选回执、教学需求与学习反馈</p></div></div><div class="row">${badge('预览快照 · 未实联','amber')}<button data-action="connection">检查连接（演示）</button></div></div><div class="connection"><div class="row"><div class="connection-symbol">W</div><div><h3>WORK-LAB</h3><p>真实实践与技术复现；可按需提供执行支持</p></div></div><div class="row">${badge('未连接')}<button data-action="connection">检查连接（演示）</button></div></div><div class="grid2 equal">${panel('创意软件与外部执行器',table(['工具','支持范围','当前状态'],[['Illustrator','文本 / 路径 / 文档操作','待宿主验证'],['Photoshop','图层 / 局部修改 / 保存','待宿主验证'],['外部 Agent','能力包 / 显式交接','按实际接口声明'],['其他品类软件','按能力具体适配','未测试不称支持']]))}${panel('知识快照与版本',facts([['模式','预览快照'],['版本','k-layout@3（示例）'],['用途','展示页面与离线边界'],['新鲜度','未与 AAOS 核对'],['在途任务','保持原知识版本'],['更新行为','新任务使用新版本或明确重算']]))}</div><div class="grid2 equal">${notice('各项目只写自己的业务状态。不共享业务数据库，不把 WORK-LAB 或 AAOS 当总控制器。')}${notice('撤销、未知权利或要求在线复核的任务应按条件暂停；允许的本地分析可以继续。','amber')}</div>${panel('诊断与当前依据',`<div class="row spread"><div><strong>规则版本与来源</strong><p class="muted">生产环境从正式权威入口读回，不以当前效果图替代产品定位。</p></div><button data-action="diagnostic">查看预览诊断</button></div>`)}</div>`;}
function states(){return head('UI STATES / RECOVERY & ACCESS','每一种状态，都有下一步。','没有数据、没有权限与没有证据是不同的情况；不把未知显示为失败或成功。',btn('返回能力目录','catalog'))+`<div class="states">${[
['加载中','正在读取能力与权限。','保留布局，避免闪烁；不出现旧数据。','loading'],['没有匹配结果','调整领域、方法或输出筛选。','清除筛选','empty'],['资格未知','有资料，但没有可用的资格证据。','查看实际范围','unknown'],['AAOS 离线','允许的知识快照仍可用于本地分析。','查看快照条件','offline'],['无权访问','不返回受限标题、缩略图或计数。','返回可用内容','denied'],['动作结果不确定','宿主超时，先对账再决定是否重试。','核对并恢复','timeout'],['版本冲突','本次提交基于旧版本，需要查看差分。','对比后重新提交','conflict'],['任务已取消','保留已确认结果与未完成检查。','查看剩余材料','cancelled'],['反馈暂未发出','只有允许出域的摘要才能进入待发队列。','查看本地反馈','queued']
].map(([n,d,a,k])=>`<section class="state-card" data-component="状态-${k}">${badge(k,['timeout','conflict','unknown'].includes(k)?'amber':'blue')}<h3>${n}</h3><p>${d}</p>${k==='loading'?'<div class="skeleton"></div><div class="skeleton"></div>':btn(a,k==='timeout'?'recovery':k==='queued'?'feedback':'catalog')}</section>`).join('')}</div><div class="line"></div>${notice('状态由真实对象与回执驱动；不得用固定文字或随机百分比伪造进度。')}`;}
function components(){return head('DESIGN SYSTEM / IMPLEMENTATION','统一视觉，完整状态。','沿用现有技术栈，复用明确的颜色、间距与行为；品牌蓝用于聚焦内容。',btn('切换浅色',null))+`<div class="grid2 equal"><div class="stack">${panel('颜色与语义',`<div class="grid3">${[['背景','--bg'],['卡片','--panel'],['强调蓝','--accent'],['成功','--success'],['待核验','--warn'],['错误','--danger']].map(([n,v])=>`<div><div style="height:66px;border:1px solid var(--line);border-radius:7px;background:var(${v})"></div><p>${n}</p><small>${v}</small></div>`).join('')}</div>`)}${panel('字体与层级',`<h1>专业设计，清晰执行。</h1><h2 style="margin-top:12px">页面小标题 / 19 px</h2><p>正文 / 14 px，使用真实文案与可编辑文本。</p><small>辅助信息 / 12 px；不将文字烘焙到背景图。</small>`)}${panel('按钮与交互',`<div class="row">${btn('主要动作',null,'primary')}${btn('次要动作')}${btn('低频动作',null,'ghost')}<button disabled>条件未满足</button></div><p class="muted">焦点可见，触控目标不小于 44 px；悬停只增强边界，不替代文字说明。</p>`)}</div><div class="stack">${panel('资格与状态',`<div class="row wrap">${badge('可分析','blue')}${badge('执行已核验','green')}${badge('待真人确认','amber')}${badge('证据未知')}${badge('已撤销','red')}</div><div class="line"></div>${notice('查看适用条件与下一步。')}<div style="height:12px"></div>${notice('正式交付资格尚未满足。','amber')}`)}${panel('表单与引用',`<div class="fields"><label class="full"><span>知识引用</span><input value="knowledge_id / revision"></label><label class="full"><span>交付目标</span><select><option>目标生成包</option><option>最终媒体</option><option>原生工程</option></select></label><label class="full"><span>修改要求</span><textarea>只改变指定对象，保留其余内容。</textarea></label></div>`)}${panel('布局与动效',facts([['桌面','232 px 导航 / 40 px 内容边距'],['组件间距','8 / 12 / 16 / 24 / 32 px'],['圆角','控件 7 / 卡片 10 px'],['描边','1 px 低对比冷灰蓝'],['动效','生产可用 140–220 ms 状态过渡'],['减少动态','遵循 prefers-reduced-motion']]))}</div></div>`;}
const pages={catalog,capability,input,analysis,plan,running,recovery,results,result,jury,delivery,feedback,teaching,connections,states,components};
const pageLabels={catalog:'能力资产',capability:'能力详情',input:'输入与目标',analysis:'分析与方案',plan:'目标生成包',running:'制作与核验',recovery:'恢复与对账',results:'成果与反馈',result:'产物与改稿',jury:'版本评审',delivery:'交付预检',feedback:'反馈与候选',teaching:'教学需求',connections:'连接与诊断',states:'界面状态',components:'组件规范'};
function render(){const route=location.hash.slice(1)||'catalog';const key=pages[route]?route:'catalog';const group=['catalog','capability'].includes(key)?'catalog':['results','result','jury','delivery','feedback'].includes(key)?'results':['connections','states','components'].includes(key)?'connections':'input';const nav=[['catalog','asset','能力资产'],['input','make','分析与制作'],['results','result','成果与反馈']];document.body.classList.toggle('light',new URLSearchParams(location.search).get('theme')==='light');document.title=`DESIGN-LAB · ${pageLabels[key]}`;document.querySelector('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#catalog" aria-label="DESIGN-LAB 首页"><div class="brand-mark" aria-hidden="true"></div><div class="wordmark">DESIGN<em>-</em>LAB<small>设计实验室</small></div></a><div class="navcaption">专业能力与制作</div><nav class="nav">${nav.map(([r,i,t])=>`<a href="#${r}" ${group===r?'aria-current="page"':''} class="${group===r?'active':''}">${icon(i)}${t}</a>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav"><a href="#connections" class="${group==='connections'?'active':''}">${icon('link')}连接与设置</a><a href="#states">${icon('settings')}状态与组件</a></nav><div class="sidebar-note"><span class="dot"></span>界面参考 / 演示模式<br><span class="muted">能力与资格按实际证据显示。<br>未连接宿主或其他项目。</span></div></div></aside><main class="main"><header class="topbar"><div class="crumb">DESIGN-LAB　/　${pageLabels[key]}</div><div class="top-actions"><span class="demo">UI 参考 · 演示数据</span><button class="ghost" data-action="theme" aria-label="切换浅色或深色主题">${document.body.classList.contains('light')?'深色':'浅色'}</button><span class="avatar">DT</span></div></header><div class="content" data-page="${key}">${pages[key]()}<footer class="footnote"><span>DESIGN-LAB · 专业能力资产与设计自动化</span><span>当前：界面参考　/　产品迁移与真实集成待执行</span></footer></div></main><nav class="mobile-nav" aria-label="移动端主导航">${nav.map(([r,i,t])=>`<a href="#${r}" class="${group===r?'active':''}">${icon(i)}${t}</a>`).join('')}<a href="#connections">${icon('link')}连接</a></nav></div>`;window.scrollTo(0,0);attach();window.previewReady=true;}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3200);}
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function draft(kind,data){try{localStorage.setItem('design-lab-ui-'+kind,JSON.stringify({...data,demo:true}));toast('已保存到当前浏览器的演示草稿；未提交生产服务。');}catch(e){toast('浏览器禁止本地保存，草稿仍可复制。');}}
function attach(){document.querySelectorAll('[data-route]').forEach(el=>el.onclick=()=>location.hash=el.dataset.route);document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{const a=el.dataset.action;if(a==='theme'){const u=new URL(location.href);u.searchParams.set('theme',document.body.classList.contains('light')?'dark':'light');location.href=u.href;}else if(a==='copy-plan'){try{await navigator.clipboard.writeText(planText);toast('已复制演示制作说明。');}catch(e){toast('请选中制作说明手动复制。');}}else if(a==='download-plan'){download('DESIGN-LAB_demo_target_package.json',JSON.stringify({demo:true,goal:'FORM STUDIES',constraints:planText,execution_status:'NOT_RUN'},null,2));}else if(a==='download-art'){const a=document.createElement('a');a.href='../assets/art/version-after.svg';a.download='DESIGN-LAB_demo_art.svg';a.click();}else if(a==='correct'){draft('correction',{note:document.querySelector('#correction').value});}else if(a==='jury'){draft('jury',{artifact_revision:'draft@2',decision:document.querySelector('#jury-decision').value,note:document.querySelector('#jury-note').value});document.querySelector('#jury-status').textContent='本地意见草稿已保存；仍没有真实评审回执。';}else if(a==='save-feedback'){draft('feedback',{category:document.querySelector('#feedback-category').value,scope:document.querySelector('#feedback-scope').value,allow:document.querySelector('#allow-feedback').checked,note:document.querySelector('#feedback-note').value});document.querySelector('#feedback-status').textContent='草稿保存在本浏览器，未发送；AAOS 受理与核验仍未发生。';}else if(a==='pause'){const paused=el.textContent==='暂停演示';el.textContent=paused?'继续演示':'暂停演示';document.querySelector('#run-label').textContent=paused?'演示已暂停':'演示运行中';}else if(a==='cancel'){document.querySelector('#run-label').textContent='演示已取消';document.querySelector('#run-state').textContent='未完成检查已保留';toast('取消仅改变演示状态。');}else if(a==='recover'){toast('这是恢复交互演示；没有宿主读回，不能确认实际恢复。');}else if(a==='patch'){draft('patch',{base_revision:'draft@2',request:document.querySelector('#patch').value});location.hash='plan';}else if(a==='connection'){toast('预览未配置服务地址，连接状态保持未实联。');}else if(a==='diagnostic'){toast('原型版本 UI-20261009-r1；无真实宿主与三项目连接。');}else{toast('参考原型：此处由真实实现接入对应对象与接口。');}});
let selected='全部领域',level='';const filter=()=>{let count=0;document.querySelectorAll('#capCards article').forEach(card=>{const q=(document.querySelector('#search')?.value||'').toLowerCase();const matches=(selected==='全部领域'||card.dataset.domainValue===selected)&&card.dataset.name.toLowerCase().includes(q)&&!['软件执行','原生交付'].includes(level);card.classList.toggle('hidden',!matches);if(matches)count++;});document.querySelector('#no-results')?.classList.toggle('hidden',count>0);};document.querySelector('#search')?.addEventListener('input',filter);document.querySelectorAll('[data-domain]').forEach(b=>b.onclick=()=>{selected=b.dataset.domain;document.querySelectorAll('[data-domain]').forEach(x=>x.classList.toggle('selected',x===b));filter();});document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=level===b.dataset.level?'':b.dataset.level;document.querySelectorAll('[data-level]').forEach(x=>x.classList.toggle('selected',x.dataset.level===level));filter();});document.querySelector('#files')?.addEventListener('change',e=>{document.querySelector('#filelist').textContent=[...e.target.files].map(f=>f.name).join(' / ')+' · 未上传，仅演示选择';});}
window.addEventListener('hashchange',render);render();
